float roundedRect(vec2 p, vec2 size, float r) {
    vec2 halfSize = size / 2.0;
    vec2 d = abs(p) - halfSize + vec2(r);
    return length(max(d, 0.0)) - r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Rectangle dimensions in pixels
    vec2 rectSize = vec2(340.0, 100.0);

    // Corner radius in pixels
    float radius = 1.0;

    // Calculate the center of the screen
    vec2 center = iResolution.xy / 2.0;

    // Position of the current fragment relative to the center
    vec2 pos = fragCoord - center;

    // Compute the signed distance to the rounded rectangle
    float maskDist = roundedRect(pos, rectSize, radius);

    // Create smooth mask using smoothstep for anti-aliasing

    float mask = smoothstep(0.0, 1.0, -maskDist);

    // Normalize coordinates within the rectangle
    vec2 uv = pos / rectSize;

    // Adjust aspect ratio to ensure correct rotation
    float aspect = rectSize.x / rectSize.y;
    vec2 adjustedUV = vec2(uv.x * aspect, uv.y);

    // Rotation based on time
    float angle = iTime;
    mat2 rotation = mat2(
        cos(angle), -sin(angle),
        sin(angle), cos(angle)
    );

    // Apply rotation to UV coordinates
    vec2 rotatedUV = rotation * adjustedUV;

    // Calculate the angle for the gradient
    float gradientAngle = atan(rotatedUV.y, rotatedUV.x);
    float t = (gradientAngle + 3.14159265359) / (2.0 * 3.14159265359);
    float t1 = t * 6.0;

    vec3 color1 = vec3(26.0/255.0, 255.0/255.0, 255.0/255.0);  // Cyan
    vec3 color2 = vec3(19.0/255.0, 58.0/255.0, 255.0/255.0);   // Blue
    vec3 color3 = vec3(102.0/255.0, 26.0/255.0, 255.0/255.0);  // Purple
    vec3 color4 = vec3(250.0/255.0, 85.0/255.0, 187.0/255.0);  // Pink
    vec3 color5 = vec3(255.0/255.0, 140.0/255.0, 26.0/255.0);  // Orange
    vec3 color6 = vec3(255.0/255.0, 194.0/255.0, 26.0/255.0);  // Yellow

    vec3 gradientColor;
    if (t1 < 1.0) {
        gradientColor = mix(color1, color2, t1);
    } else if (t1 < 2.0) {
        gradientColor = mix(color2, color3, t1 - 1.0);
    } else if (t1 < 3.0) {
        gradientColor = mix(color3, color4, t1 - 2.0);
    } else if (t1 < 4.0) {
        gradientColor = mix(color4, color5, t1 - 3.0);
    } else if (t1 < 5.0) {
        gradientColor = mix(color5, color6, t1 - 4.0);
    } else {
        gradientColor = mix(color6, color1, t1 - 5.0);
    }

    vec3 backgroundColor = vec3(0.0, 0.0, 0.0);
    vec3 color = mix(backgroundColor, gradientColor, mask);

    fragColor = vec4(color, 1.0);
}
